Task.Run(Outer);                  // from Main: the global queue

void Outer()                      // runs on pool thread P
{
    Task.Run(A);                  // P's local queue
    Task.Run(B);                  // P's local queue, after A
    Task.Factory.StartNew(C, CancellationToken.None,
        TaskCreationOptions.PreferFairness,
        TaskScheduler.Default);   // the global queue
}
// P finished Outer → takes B (from the end of its queue), then A.
// A free thread Q takes C from the global queue or steals A from the front of P's queue.

